package com.pankqx.tonefer

import com.pankqx.tonefer.crypto.SecretBox
import com.pankqx.tonefer.data.Pairing
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.fail
import org.junit.Test
import java.security.GeneralSecurityException

/** Vectors generated with PyNaCl, the library the laptop app uses. */
class CryptoTest {
    private val vectors = arrayOf(
        arrayOf("3c7c0cd38f6987a7c673431a624bb27f6604479777b1f9f5f443afff41ae3ab2", "c8a64f9e02478f051407281034eacc47437fb48e9b20c22b", "", "c8a64f9e02478f051407281034eacc47437fb48e9b20c22b428a26edc112f4a1954ca3ceacc1ca9b"),
        arrayOf("a7b749b56e66c6e00bc361399fe927ff52710a500551ad57562552da5d8de604", "0c3269835eb53d25d5dca47abb98f3a9a1bda8fa0a3b99f2", "7f", "0c3269835eb53d25d5dca47abb98f3a9a1bda8fa0a3b99f21871ea8826bde8684b9966938f5660e4cc"),
        arrayOf("38f471bb4719a8616dd677234d7f21733d937057d91401e4b19255e2151096e4", "d743388e46f3e140d372625719414986445a2cde1d258626", "cc3334db6355c2b4f5a45c99a6ec718196bd0d25ffe91c267e9c2f5f5baf35", "d743388e46f3e140d372625719414986445a2cde1d258626a8b2f84d701543bf3bd6b81d226a33a968e508d1db76b976a6858ac768cc1e65c2d03c98b5377d1b9b45597ad9fa6d"),
        arrayOf("cd3e5890bf1bce02147657a75adf90a7ade141239417b1418949b63c5e3e7f7f", "30798bc23dea5a3280fb73e95666f64bd304d920aee00672", "c41e1bd77e7e4a488ccb577d15058291a22fe9ee0167a986ddbc1573017b1c6a", "30798bc23dea5a3280fb73e95666f64bd304d920aee00672a36dcceaa261a579050c1f31c8d9c02a8ad395f66919c5fb760f4214ba900849485bfd5e35b3a12a8a35894be22ae6d5"),
        arrayOf("781b0105956574508e25bf8400ed01b4f6d21fce265b788f60814005eab66ac5", "336b90d4701b3aacc066ea219ed8eba5522731eb65dc793e", "823c0d4dd2dec2a05934a235f3659a32295b9f4b4185dad15e4edfd800a621e7d9", "336b90d4701b3aacc066ea219ed8eba5522731eb65dc793e1ccc6a1b3ab7d1b9d2fab22a408998f649df5b1532cee684642364013700afa3618548d979d292ed73f4d3273c00868465"),
        arrayOf("62cac72333c066d7be3997d57be0802a5ba212b87ae3e80d3da4027bc14566eb", "0fbb95053ace02e44a97062404daa3db79bba34d89767a6d", "e2a2f93c5f8cc84191e412948c4b6461fec3601c1043e2793b630ec68da37126411deedaa58ba38533beb054e552939ffb7ba5732ce8bc1e7479b56b0b894ba6", "0fbb95053ace02e44a97062404daa3db79bba34d89767a6d39621be8b1feab0fae3805a417d9bd8c6d8aac33391d2013fd13c9fcc57896fbb46eeccfdb101570fb96361be55b10cae295236163a440c72b5346b2c1c343d840264b406d7542e2e2a4aef71024339c"),
        arrayOf("51b0c1e52d33ae5d68d45a2e5d62e4ced34ad1052cc055175ca7785ff8dc96a4", "4ace481e9030c0660a9bfd38c44621de2f76c43a43e06b10", "42a384ed72614312f6213354d7256dc18caf7d0b16ed3247e884309cb4abf07bbaf7335c783ed0e0a8456a98b6a813a93ff58dfb08a65fe941e21ef1acc3ada6070a86ad8232dc07b35fe910ae75ced969d5b078d8ec23d44d8d4ce7c4f13db75764f85d", "4ace481e9030c0660a9bfd38c44621de2f76c43a43e06b10bddc10ed50d648c0c21c0fd68fdb8ab93ce34f7f1dc433a6be07883a31991b610233019a6d0b27aab659e7de66f1912236e3c03eb980cd07f46d14e1fea6720dcaaa059a1e392960b435c4936ee8684282c5d3e0f0065ddbf6fe65b51d710334cd8cfcdfa437f06d4c94a7e41ae91b1fd66f675c"),
        arrayOf("bf3215b35a33b9a8f01dac98f93882548c77a54e6c95a951eb23480dfc20a19b", "e7de05ff77fa4068ef8ef0d824bbd04dcd21250fd2382af3", "", ""),
    )

    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    @Test fun sealMatchesPyNaCl() {
        for ((k, n, m, box) in vectors.map { it.toList() }) {
            assertArrayEquals(hex(box), SecretBox.seal(hex(k), hex(n), hex(m)))
        }
    }

    @Test fun openMatchesPyNaCl() {
        for ((k, _, m, box) in vectors.map { it.toList() }) {
            assertArrayEquals(hex(m), SecretBox.open(hex(k), hex(box)))
        }
    }

    @Test fun tamperedDataIsRejected() {
        val (k, _, _, box) = vectors[4].toList()
        val bad = hex(box).also { it[it.size - 1] = (it[it.size - 1].toInt() xor 1).toByte() }
        try { SecretBox.open(hex(k), bad); fail("tampering not detected") } catch (_: GeneralSecurityException) { }
    }

    @Test fun randomRoundTrip() {
        val key = ByteArray(32) { it.toByte() }
        val msg = ByteArray(200_003) { (it * 31).toByte() }
        assertArrayEquals(msg, SecretBox.open(key, SecretBox.seal(key, msg)))
    }

    @Test fun tokenMatchesLaptop() {
        assertEquals("9726da7aaa5d603b8b7816e1b565a50e227b89c6195c84c0aa13631c8fbc73c9", Pairing.tokenFor(hex("23dca4c041915c6aa8f2bc2d6af8c686d59c4f10fecf2ed71a8775fc045b1bee")))
    }

    @Test fun parsesPairingLinks() {
        val p = Pairing.parse("http://10.42.0.15:8765/#k=I9ykwEGRXGqo8rwtavjGhtWcTxD-zy7XGod1_ARbG-4")
        assertNotNull(p)
        assertEquals("10.42.0.15", p!!.host)
        assertEquals(8765, p.port)
        assertArrayEquals(hex("23dca4c041915c6aa8f2bc2d6af8c686d59c4f10fecf2ed71a8775fc045b1bee"), p.key)
        assertEquals("192.168.43.2", Pairing.parse("192.168.43.2:9000/#k=I9ykwEGRXGqo8rwtavjGhtWcTxD-zy7XGod1_ARbG-4")!!.host)
        assertNull(Pairing.parse("https://example.com"))
        assertNull(Pairing.parse("http://10.0.0.1:8765/#k=short"))
    }
}
